// Fifth evaluation, AC-312 follow-up: after an own font is added in a mixed case, how long does Enter (or leaving) take until the line shows the text, and what is on screen meanwhile? 3 runs per case, alone on the machine.
const { chromium, BASE, log, FX } = require("./lib.cjs"); const { install, state } = require("./st.cjs");
const SIZES = { 1280: { viewport: { width: 1280, height: 800 } }, 390: { viewport: { width: 390, height: 844 }, hasTouch: true, isMobile: true } };
(async () => { const browser = await chromium.launch({ proxy: { server: process.env.HTTPS_PROXY } });
  for (const tag of (process.env.SIZES || "1280,390").split(",")) for (const [file, which, label] of [[FX + "chrome-justified-mixed.pdf", /^in full/, "embedded"], [process.env.FXD + "/ac283-named-only.pdf", 0, "arial-named"]]) for (const txt of (process.env.TEXTS ? JSON.parse(process.env.TEXTS) : [" नया ⸘ ok", " ř ⸘", " ⸘"])) for (let rep = 0; rep < +(process.env.REPS || 3); rep++) {
    const phone = tag !== "1280"; const ctx = await browser.newContext({ deviceScaleFactor: 2, ...SIZES[tag] }); const page = await ctx.newPage(); const reqs = []; page.on("request", (r) => reqs.push({ t: Date.now(), m: r.method(), u: r.url() }));
    await page.goto(BASE + "/edit-pdf", { waitUntil: "networkidle", timeout: 90000 }); await page.locator('input[type="file"]').first().setInputFiles(file); await page.waitForTimeout(4000); await install(page);
    const o = typeof which === "number" ? page.getByTestId("line").nth(which) : page.getByRole("option", { name: which }); const b = await o.boundingBox(); phone ? await page.touchscreen.tap(b.x + b.width - 3, b.y + b.height / 2) : await page.mouse.click(b.x + b.width - 3, b.y + b.height / 2); await page.getByTestId("line-input").waitFor(); await page.waitForTimeout(600); await page.keyboard.press("End"); await page.keyboard.insertText(txt); await page.waitForTimeout(4000);
    if (process.env.NOOWN !== "1") { const own = page.getByRole("button", { name: /own font|Your font/ }).first(); const fc = page.waitForEvent("filechooser", { timeout: 6000 }).catch(() => null); phone ? await own.tap() : await own.click(); const ch = await fc; if (!ch) { log(tag, label, "no chooser"); await ctx.close(); process.exit(1); } await ch.setFiles(process.env.FXD + "/own-dejavu.ttf"); await page.waitForTimeout(3000); } // NOOWN=1: no font is added (comparison)
    await page.locator("[data-testid=line-input]").focus(); const n0 = reqs.length; await page.keyboard.press("Enter"); const t0 = Date.now(); let last = "", tl = [], done = null;
    while (Date.now() - t0 < 20000) { const st = await state(page); const saved = st.lines.some((l) => l.endsWith(txt.slice(-3))); const busy = await page.evaluate(() => [...document.querySelectorAll("[aria-busy=true], [role=progressbar], .ed-saving, [data-saving]")].length); const k = JSON.stringify({ box: !!st.box, notice: st.notice && st.notice.text.slice(0, 80), saved, undo: st.undo, busy, live: st.live && st.live.slice(0, 40) }); if (k !== last) { tl.push("+" + (Date.now() - t0) + " " + k); last = k; } if (saved && done == null) done = Date.now() - t0; if (done != null && Date.now() - t0 > done + 800) break; await page.waitForTimeout(40); }
    log(tag, label, JSON.stringify(txt), "run", rep, "Enter → text on the line ms", done, "| timeline", tl.join("  "), "| requests after Enter", JSON.stringify(reqs.slice(n0).map((r) => "+" + (r.t - t0) + " " + r.u.split("/").slice(-2).join("/").slice(0, 50)).slice(0, 8)));
    await ctx.close(); }
  await browser.close();
})().catch((e) => { console.error(String(e).slice(0, 1200)); process.exit(1); });
